style.css:
@-moz-document domain("google.com") {
/* Change logo to the 2015-2016 version */
    img[alt="Google"] {
        content: url("https://upload.wikimedia.org/wikipedia/commons/2/2f/Google_2015_logo.svg") !important;
        height: 92px !important;
    }

    /* White clean background */
    body, html {
        background: white !important;
        font-family: Arial, sans-serif !important;
    }

    /* Classic search box style */
    .RNNXgb {
        border: 1px solid #dcdcdc !important;
        border-radius: 0px !important;
        box-shadow: none !important;
    }

    /* Classic-style buttons */
    input[type="submit"], input[type="button"] {
        background-color: #f8f9fa !important;
        border: 1px solid #c6c6c6 !important;
        color: black !important;
        font-size: 13px !important;
        padding: 5px 10px !important;
    }

    /* Remove cards and modern effects */
    .ifM9O, .card-section, .xpdopen {
        display: none !important;
    }

    /* Footer styling */
    #fbar {
        background-color: #f2f2f2 !important;
        color: #666 !important;
        font-size: 13px !important;
    }
}
